  "issues": [
    {
      "file": "src/jobwatch/cli.py",
      "lines": "83-99",
      "severity": "high",
      "description": "Ingest commits valid rows before enforcing the malformed-row threshold, so a failed ingest can still partially mutate the database."
    },
