      "file": "src/jobwatch/parsing.py",
      "lines": "71-88",
      "severity": "high",
      "description": "Elapsed parsing rejects valid Slurm formats such as MM:SS and DD-MM:SS."
    },
    {
      "file": "src/jobwatch/store.py",
      "lines": "11, 123-135, 152-166",
      "severity": "high",
      "description": "Failure reports look for OOM instead of Slurm's OUT_OF_MEMORY state, so real OOM jobs are omitted."
    },
    {
      "file": "src/jobwatch/parsing.py",
      "lines": "187-198",
      "severity": "medium",
      "description": "Rows with extra pipe-delimited columns are accepted silently because DictReader stores overflow fields under None and the parser never checks it."
    },
    {
      "file": "src/jobwatch/store.py",
      "lines": "18-23",
      "severity": "medium",
      "description": "Report commands create and initialize a new empty database when the requested DB path is wrong, hiding operator mistakes."
    },
    {
      "file": "src/jobwatch/store.py",
      "lines": "30, 61-73",
      "severity": "medium",
      "description": "Using job_id as the only primary key overwrites duplicate/requeued accounting records and cannot preserve run history."
    },
    {
      "file": "src/jobwatch/parsing.py",
      "lines": "91-106",
      "severity": "medium",
      "description": "GPU counting sums every gres/gpu-prefixed TRES, which can double-count when generic and typed GPU TRES are both present."
    },
    {
      "file": "src/jobwatch/parsing.py",
      "lines": "109-117, 120-125",
      "severity": "low",
      "description": "Timestamps are validated but not normalized, so mixed timezone-aware and naive ISO strings will compare incorrectly as SQLite text."
    },
    {
      "file": "tests/test_cli.py",
      "lines": "35-53",
      "severity": "medium",
      "description": "The malformed-threshold test asserts the nonzero exit but does not assert that the failed ingest left the database unchanged."
    }
  ],
  "lines_to_rewrite": 140,
  "approve": false
}
